-- Generated by tools/make-seed.js — a test master to try the real booking flow.
-- Open the app with ?m=test-studio. Sign in to the dashboard as owner@example.com.

insert into public.masters (id, slug, name, owner_email, timezone, style, accent, settings, booking_engine,
                            auto_confirm, min_notice_hours, max_days_ahead, cancel_window_hours, slot_step_min)
values ('7e570000-0000-4000-8000-000000000001', 'test-studio', 'Test Studio', 'owner@example.com', 'America/New_York', 'noir', '#F4A6B8',
        $settings${"tagline":"Lashes & brows — book online in a minute","city":"Atlanta, GA","address":"1080 Peachtree St NE, Suite 4B, Atlanta, GA 30309","parking":"Free 2-hour parking in the Peachtree Square garage — take a ticket, we validate at checkout. Street parking on 12th St.","phone":"+1 (404) 555-0142","instagram":"arialash.demo","heroPhoto":"https://images.pexels.com/photos/5128219/pexels-photo-5128219.jpeg?auto=compress&cs=tinysrgb&w=900","heroVideo":"","avatar":"https://images.pexels.com/photos/5128228/pexels-photo-5128228.jpeg?auto=compress&cs=tinysrgb&w=400&h=400&fit=crop&crop=top","policies":[{"title":"Deposit","text":"A $30 deposit secures your spot and goes toward your service. It is non-refundable, but it moves with you if you reschedule in time."},{"title":"Late arrivals","text":"Running late? Send a quick text. After 15 minutes we may need to shorten your service or reschedule so the next client isn't kept waiting."},{"title":"Cancellations","text":"Please cancel or reschedule at least 24 hours ahead. Later cancellations and no-shows lose the deposit."},{"title":"Fills","text":"A fill needs at least 40% of your lashes remaining. Sets from another artist are booked as a new full set."}],"prep":["Come with clean lashes — no mascara or eye makeup","Skip caffeine 2 hours before so you can relax","Take out contact lenses and bring your glasses"],"aftercare":[{"step":"Keep them dry for 24 hours","text":"No water, steam, sauna or sweaty workouts while the adhesive cures."},{"step":"Cleanse every day","text":"Wash gently with an oil-free lash shampoo and a soft brush. Clean lashes last longer."},{"step":"Brush each morning","text":"Use a clean spoolie to fluff them back into place once they're dry."},{"step":"Skip oils and mascara","text":"Oil-based removers, creams and waterproof mascara break down the bond."},{"step":"Hands off","text":"Don't rub, pick or pull. If a lash is bothering you, message us instead."},{"step":"Book your fill","text":"Come back every 2–3 weeks to keep your set looking full."}],"faq":[{"q":"How long do lash extensions last?","a":"With good aftercare a set lasts 4–6 weeks ✨ Most clients come in for a fill every 2–3 weeks to keep it full.","keywords":["last","fall out","shed","shedding","retention"]},{"q":"Is it safe for sensitive eyes?","a":"Yes 💕 We use a low-fume, medical-grade adhesive and can do a free patch test 48 hours before your appointment if you're sensitive.","keywords":["sensitive","allergy","allergic","safe","irritation","patch test","glue","adhesive","hurt","pain"]},{"q":"How should I prepare?","a":"Come with clean, makeup-free eyes, skip caffeine right before, and take out contact lenses. That's it — you get to nap while we work 😴","keywords":["prepare","before my appointment","come with","makeup","caffeine","contacts","contact lenses"]},{"q":"Can I wear mascara or eyeliner?","a":"You won't need mascara 😉 If you want liner, keep it oil-free and avoid waterproof formulas — they break down the lash bond.","keywords":["mascara","eyeliner","liner","curler","makeup remover"]},{"q":"Can I shower, swim or work out?","a":"After the first 24 hours — yes to all of it 💦 Just rinse your lashes after the pool or the gym and brush them once they're dry.","keywords":["shower","swim","swimming","pool","gym","workout","work out","sweat","beach"]},{"q":"Where are you located? Is there parking?","a":"We're in Midtown Atlanta 📍 Free 2-hour parking in the Peachtree Square garage — we validate at checkout.","keywords":["where","located","location","address","parking","park","directions"]},{"q":"How can I pay?","a":"Cards, Apple Pay, Zelle and cash all work 💳 The deposit is paid online when you book, the rest at your appointment.","keywords":["pay","payment","cash","card","apple pay","zelle","venmo","tip"]},{"q":"Can I bring someone with me?","a":"The studio is a cozy one-on-one space, so please come solo — no guests or little ones during the service 💕","keywords":["guest","kid","child","children","baby","friend","bring someone"]},{"q":"Do you fill lashes from another artist?","a":"We don't fill over another artist's work — your first visit is booked as a full set so the retention is up to our standard ✨","keywords":["another artist","another salon","someone else","other lash tech","removal","remove"]}],"splashStyle":"clean","splashEmoji":"Sparkles"}$settings$::jsonb, 'builtin', true, 2, 60, 24, 30)
on conflict (slug) do nothing;

insert into public.services (id, master_id, category, name, description, includes, duration_min, buffer_min,
                             price, deposit, photo, sort)
values
  ('7e570000-0000-4000-8000-100000000001', '7e570000-0000-4000-8000-000000000001', 'Lashes', 'Classic Full Set', 'One extension on every natural lash for a soft, mascara-like finish. The most natural look — perfect if this is your first set.',
