  ('7e570000-0000-4000-8000-100000000002', '7e570000-0000-4000-8000-000000000001', 'Lashes', 'Hybrid Full Set', 'A mix of classic lashes and handmade fans. Textured and wispy, with more fullness than classic but still everyday-soft.',
   ARRAY['Consultation & lash mapping', 'Mix of classic lashes and handmade fans', 'Textured, wispy styling', 'Aftercare kit with spoolie']::text[], 135, 15,
   150, 30, 'https://images.pexels.com/photos/5128220/pexels-photo-5128220.jpeg?auto=compress&cs=tinysrgb&w=900', 1),
  ('7e570000-0000-4000-8000-100000000003', '7e570000-0000-4000-8000-000000000001', 'Lashes', 'Volume Full Set', 'Ultra-light handmade fans on every lash for a full, fluffy, dramatic look. Great for sparse lashes or when you want the wow.',
   ARRAY['Consultation & lash mapping', 'Handmade 3D–6D fans', 'Full, fluffy styling', 'Aftercare kit & lash shampoo']::text[], 150, 15,
   180, 30, 'https://images.pexels.com/photos/5128234/pexels-photo-5128234.jpeg?auto=compress&cs=tinysrgb&w=900', 2),
  ('7e570000-0000-4000-8000-100000000004', '7e570000-0000-4000-8000-000000000001', 'Lashes', 'Lash Lift & Tint', 'Your own lashes, lifted from the root and tinted darker. No extensions, zero upkeep, lasts 6–8 weeks.',
   ARRAY['Lift with keratin treatment', 'Custom lash tint', 'Nourishing serum finish']::text[], 60, 15,
   85, 0, 'https://images.pexels.com/photos/5128267/pexels-photo-5128267.jpeg?auto=compress&cs=tinysrgb&w=900', 3),
  ('7e570000-0000-4000-8000-100000000005', '7e570000-0000-4000-8000-000000000001', 'Brows', 'Brow Lamination & Tint', 'Brow hairs are smoothed and set in place for a fuller, brushed-up shape, then tinted to match. Lasts about 6 weeks.',
   ARRAY['Brow mapping', 'Lamination & setting', 'Custom tint', 'Trim and tidy']::text[], 50, 10,
   75, 0, 'https://images.pexels.com/photos/5128259/pexels-photo-5128259.jpeg?auto=compress&cs=tinysrgb&w=900', 4),
  ('7e570000-0000-4000-8000-100000000006', '7e570000-0000-4000-8000-000000000001', 'Brows', 'Brow Shaping & Tint', 'Mapping, wax and tweeze for a clean shape that suits your face, finished with a custom tint.',
   ARRAY['Brow mapping', 'Wax & tweeze', 'Custom tint']::text[], 30, 10,
   45, 0, 'https://images.pexels.com/photos/5128275/pexels-photo-5128275.jpeg?auto=compress&cs=tinysrgb&w=900', 5),
  ('7e570000-0000-4000-8000-100000000007', '7e570000-0000-4000-8000-000000000001', 'Fills', '2-Week Fill', 'A refresh for sets that are up to 2 weeks old. Outgrown lashes are removed and gaps are filled back in.',
   ARRAY['Gentle cleanse', 'Outgrown lashes removed', 'Gaps filled to full density']::text[], 60, 10,
   65, 0, 'https://images.pexels.com/photos/5128230/pexels-photo-5128230.jpeg?auto=compress&cs=tinysrgb&w=900', 6),
  ('7e570000-0000-4000-8000-100000000008', '7e570000-0000-4000-8000-000000000001', 'Fills', '3-Week Fill', 'For sets that are 15–21 days old. You need at least 40% of your lashes left — less than that is booked as a full set.',
   ARRAY['Gentle cleanse', 'Outgrown lashes removed', 'Gaps filled to full density', 'Retention check']::text[], 75, 10,
   80, 0, 'https://images.pexels.com/photos/5128225/pexels-photo-5128225.jpeg?auto=compress&cs=tinysrgb&w=900', 7)
on conflict (id) do nothing;

-- Mon–Fri 9–1 and 2–7 (lunch break), Sat 10–4, Sunday closed
insert into public.working_hours (master_id, weekday, start_time, end_time)
select '7e570000-0000-4000-8000-000000000001'::uuid, d, t.s, t.e
  from generate_series(1, 5) d, (values (time '09:00', time '13:00'), (time '14:00', time '19:00')) t(s, e)
union all
select '7e570000-0000-4000-8000-000000000001'::uuid, 6, time '10:00', time '16:00';

-- A morning off in ten days
insert into public.time_off (master_id, start_at, end_at, reason)
select '7e570000-0000-4000-8000-000000000001'::uuid,
       (((now() at time zone 'America/New_York')::date + 10) + time '09:00') at time zone 'America/New_York',
       (((now() at time zone 'America/New_York')::date + 10) + time '13:00') at time zone 'America/New_York',
       'Dentist';

